const plusDays=(v,n)=>{const d=new Date(`${v}T12:00:00`);d.setDate(d.getDate()+Number(n));return dateISO(d)};
const dateBR=v=>v?new Date(`${v}T12:00:00`).toLocaleDateString('pt-BR'):'—';
const monthBR=v=>v?new Date(`${v}-01T12:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}):'—';
