const chargePmts=cid=>D.payments.filter(p=>p.chargeId===cid);
const totalC=c=>Object.values(c.items||{}).reduce((s,x)=>s+amount(x),0);
const paidC=c=>chargePmts(c.id).reduce((s,p)=>s+amount(p.amount),0);
const balanceC=c=>Math.max(0,Math.round((totalC(c)-paidC(c))*100)/100);
const statusC=c=>{const b=balanceC(c);if(b<.005)return'pago';if(c.dueDate<today)return'atrasado';if(paidC(c)>0)return'parcial';return'pendente'};
const statusTag=c=>{const s=statusC(c);return`<span class="tag ${s==='atrasado'?'red':s==='pendente'?'amber':s==='parcial'?'blue':''}">${{pago:'Pago',parcial:'Parcial',pendente:'Pendente',atrasado:'Atrasado'}[s]}</span>`};
const typeTag=v=>`<span class="tag ${v==='cria'?'amber':(v==='potro'||v==='potro_doma')?'blue':v==='descanso'?'muted':''}">${esc(TYPES[v]||v)}</span>`;
