function modalResult(inscId,resId,eventId){
const ev=D.events.find(x=>x.id===(eventId||S.detailEvent));
const ins=inscId?D.inscriptions.find(x=>x.id===inscId):null;
const res=resId?D.results.find(x=>x.id===resId):null;
if(!ev)return;
function v(f,def=''){return res?res[f]??def:def}
const crit=ev.scoringCriteria&&ev.scoringCriteria.length?ev.scoringCriteria:(MODALIDADES[ev.modalidade]?.criterios||[]).map(c=>({key:c.toLowerCase().replace(/\s/g,'_'),label:c}));
const a=ins?animal(ins.animalId):null;
modal(res?'Editar resultado':'Lançar resultado',esc(ev.name)+(a?' — '+esc(a.name):''),
`<div class="modal-body"><form id="result-form" novalidate>
<input type="hidden" name="recId" value="${esc(resId||'')}">
<input type="hidden" name="eventId" value="${esc(ev.id)}">
<input type="hidden" name="inscriptionId" value="${esc(inscId||ins?.id||'')}">
<input type="hidden" name="animalId" value="${esc(ins?.animalId||res?.animalId||'')}">
<div class="form-grid">
${field('Classificação (posição)','classification',v('classification'),{type:'number',min:1,placeholder:'1º, 2º, 3º...'})}
${crit.map(c=>`${field(esc(c.label||c)+' (nota)','score_'+esc(c.key||c).replace(/[^a-z0-9_]/gi,'_'),v('scores',{})[c.key||c]||'',{type:'number',min:0,max:10,step:'0.01'})}`).join('')}
${field('Nota total','totalScore',v('totalScore'),{type:'number',min:0,step:'0.01',placeholder:'Calculada automaticamente se vazio'})}
${field('Premiação (R$)','prize',v('prize'),{type:'number',min:0,step:'0.01'})}
${field('Descrição do prêmio','prizeDescription',v('prizeDescription'),{placeholder:'Faixa, troféu, dinheiro...'})}
${field('Observações','notes',v('notes'),{type:'textarea'})}
</div></form></div>`,
`${btn('Cancelar','closeModal','secondary')}<button class="btn" type="button" onclick="(function(){var __f=document.getElementById('result-form');if(__f)__f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}))})()">${ico('check')} Salvar resultado</button>`,true);}

function modalEventExpense(eventId,id){
const ev=D.events.find(x=>x.id===eventId)||D.events.find(x=>x.id===S.detailEvent);
const exp=id?D.eventExpenses.find(x=>x.id===id):null;
if(!ev)return;
function v(f,def=''){return exp?exp[f]??def:def}
const animalOpts=[['','Geral / sem animal específico'],...D.animals.map(a=>[a.id,a.name])];
const catOpts=[['inscricao','Inscrição'],['transporte','Transporte'],['alimentacao','Alimentação'],['hotel','Hospedagem'],['outro','Outro']];
modal(exp?'Editar despesa':'Nova despesa de prova',esc(ev.name),
`<div class="modal-body"><form id="event-expense-form" novalidate>
<input type="hidden" name="recId" value="${esc(id||'')}">
<input type="hidden" name="eventId" value="${esc(ev.id)}">
<div class="form-grid">
${field('Categoria *','category',v('category','inscricao'),{type:'select',required:true,options:catOpts})}
${field('Descrição','description',v('description'),{placeholder:'Detalhes da despesa'})}
${field('Valor (R$) *','amount',v('amount'),{type:'number',required:true,min:0,step:'0.01'})}
${field('Data *','date',v('date',today),{type:'date',required:true})}
${field('Animal (opcional)','animalId',v('animalId'),{type:'select',options:animalOpts})}
<div class="form-group"><label class="checkbox-line"><input type="checkbox" name="generateCharge" ${v('generateCharge')?'checked':''}> Gerar cobrança para o proprietário</label></div>
</div></form></div>`,
`${btn('Cancelar','closeModal','secondary')}<button class="btn" type="button" onclick="(function(){var __f=document.getElementById('event-expense-form');if(__f)__f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}))})()">${ico('check')} Salvar despesa</button>`);}

function pageSettings(){const c=cfg();const first=D.charges.find(x=>balanceC(x)>0);const demoOwn=owner(first?.ownerId)?.name||'João Exemplo';const demoHorse=animal(first?.animalId)?.name||'Cavalo Exemplo';const demoDue=first?.dueDate||plusDays(today,2);const demoVal=first?balanceC(first):1500;function preview(tpl){return String(tpl||'').replaceAll('{proprietario}',demoOwn).replaceAll('{animal}',demoHorse).replaceAll('{cavalo}',demoHorse).replaceAll('{valor}',money(demoVal)).replaceAll('{vencimento}',dateBR(demoDue)).replaceAll('{pix}',c.pix?`Chave PIX: ${c.pix}`:'').replaceAll('{centro}',c.centerName).replaceAll('{itens}',first?buildItemsText([first]):'• Treinamento: R$ 1.000,00\n• Hotelaria: R$ 400,00')}
return`${pageHead('Configurações','Centro de treinamento, cobranças e dados.',btn(`${ico('download')} Exportar backup`,'export','secondary'))}<div class="settings-wrap">
<section class="panel settings-panel"><h3>Identificação do centro</h3><form id="center-form" class="form-grid">${field('Nome do centro *','centerName',c.centerName,{required:true})}${field('Chave PIX (opcional)','pix',c.pix,{placeholder:'chave@pix.com ou CPF/CNPJ'})}${field('E-mail do centro','contactEmail',c.contactEmail,{type:'email'})}<div class="form-group" style="justify-content:end"><button class="btn" type="submit">${ico('check')} Salvar</button></div></form></section>
<section class="panel settings-panel"><h3>Envio de lembretes</h3><p class="hint">As mensagens são simuladas. O envio automático real requer integração com WhatsApp Business e serviço de e-mail.</p><form id="billing-form"><div class="setting-row"><div><strong>Habilitar WhatsApp</strong><small>Canal de aviso via WhatsApp Business.</small></div><label class="toggle"><input type="checkbox" name="whatsapp" ${c.whatsapp?'checked':''}><span></span></label></div><div class="setting-row"><div><strong>Habilitar e-mail</strong><small>Enviar para o endereço cadastrado.</small></div><label class="toggle"><input type="checkbox" name="email" ${c.email?'checked':''}><span></span></label></div><div class="form-grid" style="padding:18px 0">${field('Antecedência do aviso','daysBefore',c.daysBefore,{type:'select',options:[['1','1 dia antes'],['2','2 dias antes'],['3','3 dias antes'],['5','5 dias antes'],['7','7 dias antes']]})}${field('Horário desejado','sendTime',c.sendTime,{type:'select',options:[['07:00','07:00'],['08:00','08:00'],['09:00','09:00'],['10:00','10:00'],['14:00','14:00'],['17:00','17:00']]})}</div><div class="setting-row"><div><strong>Apenas mensalidades em aberto</strong></div><label class="toggle"><input type="checkbox" name="onlyPending" ${c.onlyPending?'checked':''}><span></span></label></div><div class="setting-row"><div><strong>Consolidar por proprietário</strong><small>Unir mensalidades do mesmo vencimento.</small></div><label class="toggle"><input type="checkbox" name="consolidate" ${c.consolidate?'checked':''}><span></span></label></div><div style="display:flex;justify-content:flex-end;margin-top:17px"><button class="btn" type="submit">${ico('check')} Salvar regras</button></div></form></section>
<section class="panel settings-panel"><h3>Modelos de mensagem</h3><p class="hint">Variáveis: {proprietario}, {animal}, {valor}, {vencimento}, {itens}, {pix}, {centro}</p><form id="templates-form" class="form-grid">${field('Texto WhatsApp','waTemplate',c.waTemplate,{type:'textarea',full:true,required:true})}${field('Assunto e-mail','emailSubject',c.emailSubject,{full:true,required:true})}${field('Corpo do e-mail','emailTemplate',c.emailTemplate,{type:'textarea',full:true,required:true})}<div class="form-group full" style="align-items:flex-end"><button class="btn" type="submit">${ico('check')} Salvar mensagens</button></div></form><div class="divider"></div><strong style="font-size:12px">Prévia do WhatsApp</strong><div class="message-preview">${esc(preview(c.waTemplate))}</div><div style="margin-top:12px">${btn(`${ico('send')} Simular cobranças`,'simulateReminders','soft')}</div></section>
<section class="panel settings-panel"><h3>Backup e dados locais</h3><p class="hint">Os dados ficam neste dispositivo/navegador. Exporte cópias regularmente.</p><div class="actions">${btn(`${ico('download')} Exportar JSON`,'export','soft')}${btn(`${ico('upload')} Importar JSON`,'import','secondary')}${btn(`${ico('refresh')} Restaurar demonstração`,'reset','danger')}</div><input type="file" id="import-file" accept=".json,application/json" hidden><div class="alert-card" style="margin-top:14px">${ico('shield')}<span>O backup pode conter dados pessoais e financeiros. Armazene com segurança. A importação <strong>substitui todos os dados locais</strong>.</span></div><p class="hint" style="margin-top:12px;text-align:right">Equus v1.0 · Dados protegidos na nuvem</p></section><section class="panel settings-panel"><h3>${ico('users')} Usuários</h3>${(currentUser?.role==='admin'||currentUser?.role==='manager')?`<div>${D.users.map(u=>`<div class="setting-row"><div><strong>${esc(u.name)}</strong><small>${ROLES_PT[u.role]||u.role} &nbsp;·&nbsp; @${esc(u.username)}</small></div>${u.id!==currentUser?.id?btn('Trocar senha','resetPwd','secondary',`data-id="${u.id}"`):''}</div>`).join('')}</div>`:'<p class="hint">Apenas administradores podem gerenciar usuários.</p>'}</section>
<section class="panel settings-panel"><h3>${ico('database')} Nuvem</h3><p class="hint">Todos os dados são salvos diretamente no Supabase. Qualquer dispositivo com login pode acessar os mesmos dados em tempo real.</p><div class="alert-card" style="margin-top:8px">${ico('shield')}<span><strong>Dados protegidos na nuvem.</strong> Use o botão abaixo para backup local adicional.</span></div></section>
${D.notices.length?panel('Histórico de simulações','',`<div class="notice-log">${D.notices.slice().reverse().slice(0,8).map(n=>`<div><div><strong style="font-size:12px">${ownerName(n.ownerId)} · ${esc(n.channel)}</strong><p>${new Date(n.createdAt).toLocaleString('pt-BR')}</p></div><span class="tag muted">Simulado</span></div>`).join('')}</div>`):panel('Simulações','',empty('Sem simulações','Teste o fluxo de cobrança.'))}
</div>`}
