// ── EXPORT / IMPORT ───────────────────────────────────────────────────────
async function exportData(){const data={version:2,exportedAt:new Date().toISOString(),animals:D.animals,owners:D.owners,activities:D.activities,healthRecords:D.healthRecords,charges:D.charges,payments:D.payments,tasks:D.tasks,notices:D.notices,settings:D.settings};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`equus-backup-${today}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);toast('Backup preparado para download.')}
async function importData(file){if(!file)return;try{const raw=await file.text();const d=JSON.parse(raw);if(!d||!Array.isArray(d.animals)||!Array.isArray(d.owners))throw new Error('Formato inválido');if(!confirm(`Importar backup com ${d.animals.length} animais e ${(d.charges||[]).length} mensalidades? Isso substituirá todos os dados locais.`))return;const stores=['animals','owners','activities','healthRecords','charges','payments','tasks','notices'];for(const s of stores)await IDB.clear(s);await IDB.putMany('animals',d.animals||[]);await IDB.putMany('owners',d.owners||[]);await IDB.putMany('activities',d.activities||[]);await IDB.putMany('healthRecords',d.healthRecords||[]);await IDB.putMany('charges',d.charges||[]);await IDB.putMany('payments',d.payments||[]);await IDB.putMany('tasks',d.tasks||[]);await IDB.putMany('notices',d.notices||[]);if(d.settings){for(const[k,v]of Object.entries(d.settings))await IDB.put('settings',{key:k,value:v})}await loadAll();S.view='dashboard';render();toast('Backup importado com sucesso.');}catch(e){toast('Não foi possível importar: '+e.message,'error')}}
